INSERT INTO `supervision_categories` VALUES (1,1,'1. Pembelajaran Mendalam','Mindful, Meaningful, Joyful, Kritis, Kreatif, Kolaborasi, Refleksi',1,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(2,1,'2. Integrasi KURMAA','Keimanan, Al-Qur\'an, Adab, Ilmu & Amal, Karakter Qur\'ani',2,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(3,1,'3. Keterlibatan dan Perkembangan Siswa','Student Agency, Diferensiasi, Asesmen Formatif, Pertumbuhan Siswa',3,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(4,2,'1. Perencanaan Pembelajaran & Perangkat Ajar','Modul ajar, integrasi KURMAA, diferensiasi, asesmen awal, media TPACK',1,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(5,2,'2. Pelaksanaan Pembelajaran Mendalam & Kepemimpinan Kelas','Keterlaksanaan runtut, MMJ, adab islami, student agency, HOTS, manajemen kelas, refleksi',2,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(6,2,'3. Asesmen & Evaluasi Hasil Belajar','Rubrik KKTP, jurnal observasi adab, remedial/pengayaan, portofolio, laporan perkembangan',3,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(7,2,'4. Komitmen & Pengembangan Profesionalitas Guru','Kedisiplinan, keaktifan komunitas belajar, pengembangan mandiri, keterbukaan supervisi',4,1,'2026-10-20 02:10:08','2026-10-20 02:10:08');
