INSERT INTO `supervision_rubric_items` VALUES (1,1,'pm1','Berkesadaran (Mindful)','Guru membangun kesiapan belajar, perhatian, dan kesadaran siswa terhadap tujuan pembelajaran.',1,4,1.00,1,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(2,1,'pm2','Berkesadaran (Mindful)','Siswa memahami mengapa mereka mempelajari materi tersebut dan kaitannya dengan kehidupan.',1,4,1.00,2,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(3,1,'pm3','Bermakna (Meaningful)','Materi dikaitkan dengan pengalaman, kehidupan nyata, lingkungan, atau permasalahan yang dekat dengan siswa.',1,4,1.00,3,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(4,1,'pm4','Bermakna (Meaningful)','Siswa mampu menghubungkan pengetahuan baru dengan pengetahuan/pengalaman sebelumnya.',1,4,1.00,4,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(5,1,'pm5','Menggembirakan (Joyful)','Guru menciptakan suasana belajar yang positif, aman, aktif, dan menyenangkan.',1,4,1.00,5,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(6,1,'pm6','Menggembirakan (Joyful)','Siswa terlihat antusias, terlibat, berani bertanya, berdiskusi, mencoba, atau menyampaikan pendapat.',1,4,1.00,6,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(7,1,'pm7','Berpikir Kritis','Guru memberikan pertanyaan/tugas yang mendorong siswa menganalisis, memberikan alasan, memecahkan masalah, atau mengambil keputusan.',1,4,1.00,7,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(8,1,'pm8','Kreativitas','Siswa diberi kesempatan menghasilkan ide, solusi, karya, atau cara penyelesaian yang beragam.',1,4,1.00,8,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(9,1,'pm9','Kolaborasi & Komunikasi','Siswa bekerja sama, berdiskusi, mendengarkan, dan menyampaikan gagasan dengan baik.',1,4,1.00,9,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(10,1,'pm10','Refleksi','Guru memberikan kesempatan kepada siswa untuk merefleksikan proses dan hasil belajarnya.',1,4,1.00,10,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(11,2,'kr1','Iman','Guru mengaitkan pembelajaran dengan kesadaran kepada Allah SWT sesuai konteks materi secara alami dan tidak dipaksakan.',1,4,1.00,11,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(12,2,'kr2','Iman','Pembelajaran menumbuhkan rasa syukur, tanggung jawab, kejujuran, amanah, atau nilai keimanan lainnya.',1,4,1.00,12,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(13,2,'kr3','Al-Qur\'an','Guru menghubungkan materi dengan ayat Al-Qur\'an/hadits atau nilai Qur\'ani yang relevan dengan materi.',1,4,1.00,13,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(14,2,'kr4','Al-Qur\'an','Siswa diarahkan untuk melihat ilmu sebagai bagian dari upaya memahami tanda-tanda kebesaran Allah dan memberikan kemaslahatan.',1,4,1.00,14,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(15,2,'kr5','Adab','Guru menjadi teladan dalam sikap, bahasa, kedisiplinan, kesantunan, dan penghormatan kepada siswa.',1,4,1.00,15,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(16,2,'kr6','Adab','Siswa menunjukkan adab dalam belajar: menghormati guru, teman, ilmu, lingkungan, dan menjaga amanah.',1,4,1.00,16,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(17,2,'kr7','Ilmu & Amal','Guru membantu siswa memahami bagaimana pengetahuan yang dipelajari dapat diterapkan dalam kehidupan nyata.',1,4,1.00,17,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(18,2,'kr8','Karakter Qur\'ani','Pembelajaran mendorong tumbuhnya karakter seperti jujur, disiplin, bertanggung jawab, peduli, sabar, mandiri, dan amanah.',1,4,1.00,18,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(19,3,'ks1','Student Agency','Siswa diberi ruang untuk bertanya, memilih, berpendapat, mencoba, atau mengambil tanggung jawab dalam pembelajaran.',1,4,1.00,19,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(20,3,'ks2','Diferensiasi','Guru memperhatikan perbedaan kesiapan, kebutuhan, kemampuan, atau karakter belajar siswa.',1,4,1.00,20,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(21,3,'ks3','Asesmen Formatif','Guru melakukan pengecekan pemahaman selama proses pembelajaran dan memberikan umpan balik.',1,4,1.00,21,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(22,3,'ks4','Pertumbuhan Siswa','Guru tidak hanya berfokus pada hasil akademik, tetapi juga perkembangan sikap, keterampilan, dan karakter siswa.',1,4,1.00,22,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(23,4,'kp1','Kelengkapan Modul Ajar','Guru menyusun Modul Ajar / RPP yang lengkap sesuai capaian pembelajaran dan alur tujuan pembelajaran.',1,4,1.00,1,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(24,4,'kp2','Integrasi KURMAA','Perencanaan memuat integrasi nilai keimanan, Al-Qur\'an, dan pembiasaan adab secara jelas.',1,4,1.00,2,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(25,4,'kp3','Desain Diferensiasi','Modul memuat pemetaan kebutuhan siswa (gaya belajar, kesiapan, variasi produk/proses).',1,4,1.00,3,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(26,4,'kp4','Rencana Asesmen Formatif','Tersedia instrumen asesmen awal dan formatif untuk memantau perkembangan belajar siswa.',1,4,1.00,4,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(27,4,'kp5','Kesesuaian Media & TPACK','Penggunaan media pembelajaran dan teknologi yang mendukung pembelajaran interaktif.',1,4,1.00,5,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(28,5,'kl1','Keterlaksanaan Pembelajaran','Kegiatan pembelajaran terlaksana runtut sesuai modul ajar dari pembukaan hingga penutup.',1,4,1.00,6,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(29,5,'kl2','Pembelajaran Mendalam','Menciptakan pengalaman belajar Mindful, Meaningful, dan Joyful yang relevan.',1,4,1.00,7,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(30,5,'kl3','Penguatan Adab & Karakter','Guru secara konsisten menegakkan adab islami, bahasa santun, dan keteladanan positif.',1,4,1.00,8,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(31,5,'kl4','Keterlibatan Siswa (Agency)','Siswa aktif bertanya, berdiskusi, dan mengambil peran kepemimpinan dalam kelompok.',1,4,1.00,9,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(32,5,'kl5','Keterampilan Berpikir Kritis','Guru memfasilitasi pertanyaan HOTS dan pemecahan masalah konteks kehidupan nyata.',1,4,1.00,10,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(33,5,'kl6','Pemanfaatan Lingkungan','Memanfaatkan lingkungan sekolah / media digital sebagai sumber belajar efisien.',1,4,1.00,11,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(34,5,'kl7','Manajemen Waktu & Kelas','Pengelolaan waktu dan pengondisian kelas kondusif, tertib, dan inklusif.',1,4,1.00,12,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(35,5,'kl8','Umpan Balik Instan','Guru memberikan umpan balik langsung (afirmatif dan korektif) selama proses belajar.',1,4,1.00,13,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(36,5,'kl9','Integrasi Ayat / Hadits','Guru mengaitkan materi secara bermakna dengan ayat Al-Qur\'an/Hadits yang relevan.',1,4,1.00,14,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(37,5,'kl10','Refleksi Pembelajaran','Guru mengajak siswa menyimpulkan materi dan merefleksikan hikmah pembelajaran.',1,4,1.00,15,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(38,6,'ka1','Rubrik Penilaian Jelas','Asesmen dilengkapi rubrik kriteria ketercapaian tujuan pembelajaran (KKTP) yang terukur.',1,4,1.00,16,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(39,6,'ka2','Penilaian Sikap & Adab','Melakukan jurnal observasi adab dan perkembangan karakter siswa secara berkala.',1,4,1.00,17,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(40,6,'ka3','Tindak Lanjut Asesmen','Memanfaatkan hasil asesmen untuk program remedial dan pengayaan siswa.',1,4,1.00,18,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(41,6,'ka4','Dokumentasi Portofolio','Menyimpan dan mendokumentasikan hasil karya / portofolio siswa secara rapi.',1,4,1.00,19,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(42,6,'ka5','Laporan Perkembangan','Menyampaikan umpan balik perkembangan siswa kepada orang tua / wali secara konstruktif.',1,4,1.00,20,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(43,7,'kd1','Kedisiplinan & Kehadiran','Guru hadir tepat waktu, disiplin administrasi, dan menunjukkan etos kerja islami.',1,4,1.00,21,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(44,7,'kd2','Keaktifan Komunitas Belajar','Aktif dalam MGMP / KKG internal sekolah dan berbagi praktik baik dengan sesama guru.',1,4,1.00,22,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(45,7,'kd3','Pengembangan Diri','Mengikuti pelatihan / web seminar / literasi untuk meningkatkan kompetensi secara mandiri.',1,4,1.00,23,1,'2026-10-20 02:10:08','2026-10-20 02:10:08'),(46,7,'kd4','Keterbukaan Supervisi','Respektif terhadap masukan supervisi dan berkomitmen menjalankan Teacher Growth Plan.',1,4,1.00,24,1,'2026-10-20 02:10:08','2026-10-20 02:10:08');
