CREATE TABLE `weekly_schedules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `unit_id` int unsigned NOT NULL,
  `target_type` enum('student','staff') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'student',
  `grade_id` int unsigned DEFAULT NULL,
  `class_group_id` int unsigned DEFAULT NULL,
  `schedule_type` enum('reguler','eskul') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'reguler',
  `name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `day_name` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `day_code` int NOT NULL,
  `student_in` time NOT NULL,
  `student_late` time NOT NULL,
  `student_out` time NOT NULL,
  `staff_in` time NOT NULL,
  `staff_late` time NOT NULL,
  `staff_out` time NOT NULL,
  `is_overnight` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` enum('active','inactive') COLLATE utf8mb4_general_ci DEFAULT 'active',
  PRIMARY KEY (`id`),
  KEY `idx_ws_grade` (`grade_id`),
  KEY `idx_ws_class_group` (`class_group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
